<script setup>
import { computed, ref, onMounted } from 'vue'
import { X, Check, ShieldCheck, ArrowRight, LockKeyhole, HandCoins, CreditCard, Plus, Wallet, UserPlus, Landmark } from 'lucide-vue-next'
import StatusBadge from './StatusBadge.vue'
import LoanSchedule from './LoanSchedule.vue'
import { get, identifier, money, label, date, day, message } from '../services/api'
const props = defineProps({ module: String, item: Object, can: Function, currentUser: Object, lookups: Object })
const emit = defineEmits(['close','action','changed'])
const dialog=ref(), content=ref(null), error=ref(''), busy=ref(true)
const application=computed(() => content.value?.solicitud || props.item)
onMounted(async () => {
 dialog.value.showModal()
 try {
  if(props.module==='solicitudes') content.value=await get(`/solicitudes/${identifier(props.item)}`)
  if(props.module==='creditos') content.value={credito:await get(`/creditos/${identifier(props.item)}`)}
  if(props.module==='cuentas') content.value=await get(`/cuentas/${identifier(props.item)}/movimientos`)
  if(props.module==='tarjetas') content.value=await get(`/tarjetas/${identifier(props.item)}/estados-cuenta`)
  if(props.module==='clientes') content.value=await get(`/clientes/${identifier(props.item)}/acceso`)
  if(props.module==='empresas') content.value=await get(`/empresas/${identifier(props.item)}`)
 } catch(e) { error.value=message(e) }
 finally { busy.value=false }
})
// Gestiones from Banca Virtual arrive already evaluated by CP Analítica and accepted: they only need the bank's approval.
const fromBank=computed(()=>application.value.origen==='banca_virtual')
const transitions=computed(()=>({en_evaluacion:fromBank.value?['emitida']:[],revision_manual:['aprobada'],aprobada:['aceptada','cancelada'],aceptada:['en_tramite'],en_tramite:['emitida']}[application.value.estado] || []))
const maximum=computed(()=>application.value.limite_aprobado_centavos ?? application.value.limite_solicitado_centavos)
const applicant=computed(()=>Object.entries({'Cliente':application.value.solicitante?.nombre_completo,'DPI':application.value.solicitante?.dpi_enmascarado,'Correo':application.value.solicitante?.correo_electronico,'Teléfono':application.value.solicitante?.telefono,'NIT':application.value.solicitante?.nit,'Tipo de empleo':application.value.solicitante?.tipo_empleo,'Ingresos mensuales':application.value.solicitante?.ingresos_mensuales_q && 'Q '+application.value.solicitante.ingresos_mensuales_q,'Antigüedad laboral':application.value.solicitante?.antiguedad_laboral_meses != null && application.value.solicitante.antiguedad_laboral_meses+' meses','Gestión en Banca':application.value.gestion_ref && '#'+application.value.gestion_ref}).filter(([,v])=>v))
const actions={aprobada:'Aprobar revisión',aceptada:'Registrar aceptación',cancelada:'Cancelar gestión',en_tramite:'Iniciar trámite',emitida:'Aprobar'}
const loan=computed(()=>content.value?.credito)
const card=computed(()=>content.value?.tarjeta)
const accountNumber=id=>(props.lookups?.cuentas || []).find(a=>identifier(a)===id)?.numero || '—'
const companyName=id=>(props.lookups?.empresas || []).find(c=>identifier(c)===id)?.nombre
const owner=computed(()=>(props.lookups?.clientes || []).find(c=>identifier(c)===props.item.cliente_id))
const canApprovePayroll=computed(()=>props.can('planillas.approve') && props.item.estado==='pendiente_autorizacion')
</script>
<template><dialog ref="dialog" class="detail-dialog" @cancel.prevent="$emit('close')"><div class="dialog-heading"><div><p class="eyebrow">DETALLE DE {{ ({solicitudes:'Gestiones',creditos:'Préstamos'}[module] || label(module)).toUpperCase() }}</p><h2>{{ item.folio || item.nombre || item.name || item.numero || item.referencia || label(item.action) }}</h2></div><button class="icon-button" aria-label="Cerrar detalle" @click="$emit('close')"><X :size="22"/></button></div><div class="dialog-body"><div v-if="error" class="error-box" role="alert">{{ error }}</div><p v-if="busy" class="loading">Consultando información…</p>
<template v-else-if="module==='solicitudes'"><div class="detail-status"><StatusBadge :value="application.estado"/><span class="muted">Versión {{ application.version }}</span></div><div class="detail-stats"><div><small>Producto solicitado</small><b>{{ label(application.producto) }}</b></div><div><small>Monto solicitado</small><b>{{ money(application.limite_solicitado_centavos) }}</b></div><div><small>{{ application.limite_aprobado_centavos == null ? 'Máximo a asignar' : 'Máximo de Analítica' }}</small><b>{{ application.tipo==='debito' ? 'No aplica' : money(maximum) }}</b></div></div><div v-if="application.decision" class="notice">{{ application.decision.motivo }}<small>Referencia de CP Analítica: {{ application.decision.referencia }}</small></div><div v-if="application.estado==='en_evaluacion' && fromBank" class="notice">Evaluada por CP Analítica y aceptada por el cliente en Banca Virtual. Revisa los datos y apruébala definiendo sus condiciones.</div><div v-else-if="application.estado==='en_evaluacion'" class="notice">Esperando la evaluación de CP Analítica.</div><template v-if="applicant.length"><h3>Datos del solicitante</h3><dl class="detail-list"><template v-for="[key,value] in applicant" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl></template>
 <template v-if="loan"><h3><HandCoins :size="18"/> Préstamo {{ loan.referencia }}</h3><LoanSchedule :loan="loan"/><div v-if="can('creditos.pay') && loan.estado==='vigente'" class="detail-actions"><button class="primary" @click="$emit('action','pago-credito',loan)">Registrar pago<ArrowRight :size="16"/></button></div></template>
 <template v-if="card"><h3><CreditCard :size="18"/> Tarjeta {{ card.referencia }}</h3><div class="detail-stats"><div><small>Límite</small><b>{{ money(card.limite_centavos) }}</b></div><div><small>Deuda actual</small><b>{{ money(card.principal_centavos + card.interes_centavos) }}</b></div><div><small>Corte / pago</small><b>{{ card.dia_corte ? `Día ${card.dia_corte} / día ${card.dia_pago}` : 'No aplica' }}</b></div></div><p v-if="card.cargo_automatico" class="muted">Cargo automático del saldo de cada corte a la cuenta {{ accountNumber(card.cuenta_id) }}.</p><div v-for="row in card.estados_cuenta" :key="row.id" class="statement-card"><div><b>Corte {{ day(row.fecha_corte) }}</b><strong>{{ money(row.saldo_centavos) }}</strong></div><p>Pagado: {{ money(row.abonado_centavos ?? row.pagado_centavos) }} · mínimo {{ money(row.minimo_centavos) }}</p><small>Pago el {{ day(row.fecha_pago) }}<template v-if="row.cargo_automatico"> · cargo automático: {{ label(row.cargo_automatico.resultado) }} {{ money(row.cargo_automatico.monto_centavos) }}</template></small></div></template>
 <div v-if="application.resolucion" class="notice">Aprobada por el banco: <strong>{{ money(application.limite_asignado_centavos) }}</strong><small>{{ application.resolucion.nota }}</small></div><h3>Recorrido de la gestión</h3><div class="timeline"><article v-for="event in content?.historial" :key="event.id"><span class="timeline-dot"><Check :size="13"/></span><div><b>{{ event.action==='pago_prestamo' ? 'Pago de préstamo' : label(event.estado) }}</b><p>{{ event.note }}</p><small>{{ date(event.created_at) }} · {{ event.actor==='service:banca' ? 'Banca Virtual' : event.actor==='sistema:cobros' ? 'Débito automático' : event.actor }}</small></div></article></div><p class="integrity" :class="{'error-text':content?.integridad_verificada === false}"><ShieldCheck :size="17"/>{{ content?.integridad_verificada ? 'Integridad del historial verificada' : 'No se pudo verificar la integridad del historial' }}</p><div v-if="can('solicitudes.manage')" class="detail-actions"><button v-for="target in transitions" :key="target" class="primary" :class="{secondary:target==='cancelada'}" @click="$emit('action','transicion',{...application,target})">{{ actions[target] }}<ArrowRight :size="16"/></button></div></template>
<template v-else-if="module==='creditos'"><template v-if="loan"><p class="muted">{{ label(loan.producto) }} · titular {{ (lookups?.clientes || []).find(c=>identifier(c)===loan.cliente_id)?.nombre || 'cliente' }} · desembolsado {{ day(loan.desembolsado_el) }}</p><LoanSchedule :loan="loan"/><div v-if="can('creditos.pay') && loan.estado==='vigente'" class="detail-actions"><button class="primary" @click="$emit('action','pago-credito',loan)">Registrar pago<ArrowRight :size="16"/></button></div></template></template>
<template v-else-if="module==='empresas'"><template v-if="content"><dl class="detail-list compact"><dt>Razón social</dt><dd>{{ content.razon_social || content.nombre }}</dd><dt>NIT</dt><dd>{{ content.nit }}</dd><dt>Representante legal</dt><dd>{{ content.representante_legal || '—' }}</dd></dl><div class="detail-status"><span class="muted">Saldo en todas sus cuentas<template v-if="content.correo"> · {{ content.correo }}</template><template v-if="content.telefono"> · {{ content.telefono }}</template></span><strong>{{ money(content.saldo_total_centavos) }}</strong></div><div class="detail-stats"><div><small>Cuentas</small><b>{{ content.cuentas.length }}</b></div><div><small>Colaboradores</small><b>{{ content.colaboradores }}</b></div><div><small>Planillas pagadas</small><b>{{ content.planillas_pagadas }}</b></div></div>
 <h3><Landmark :size="18"/> Cuentas de la empresa</h3><div v-for="a in content.cuentas" :key="a.id" class="movement"><div><b>{{ a.numero }} · {{ label(a.tipo) }}</b><small>{{ a.nombre }}{{ a.principal ? ' · paga las planillas' : '' }} · {{ label(a.estado) }}</small></div><b>{{ money(a.saldo_centavos) }}</b></div><div v-if="can('empresas.write')" class="detail-actions"><button class="primary" @click="$emit('action','deposito-empresa',content)"><Wallet :size="16"/>Depósito o retiro</button><button class="secondary" @click="$emit('action','cuenta-empresa',content)"><Plus :size="16"/>Abrir otra cuenta</button></div>
 <h3><UserPlus :size="18"/> Usuarios de la empresa</h3><p v-if="!content.representantes.length" class="notice">La empresa todavía no tiene usuarios. Crea uno para que cargue y autorice sus planillas.</p><div v-for="u in content.representantes" :key="u.id" class="movement"><div><b>{{ u.name }}</b><small>{{ u.email }} · {{ u.active ? 'Activo' : 'Inactivo' }}</small></div><span v-if="can('usuarios.write')" class="inline-actions"><button class="text-button" @click="$emit('action','contrasena-usuario',u)">Contraseña</button><button class="text-button" @click="$emit('action','editar-representante',u)">{{ u.active ? 'Desactivar' : 'Activar' }}</button></span></div><div v-if="can('usuarios.write')" class="detail-actions"><button class="secondary" @click="$emit('action','usuario-empresa',content)"><UserPlus :size="16"/>Crear usuario de la empresa</button></div>
 <h3>Movimientos recientes</h3><div v-for="row in content.movimientos" :key="row.id" class="movement"><div><b>{{ row.concepto }}</b><small>{{ row.cuenta_numero }} · {{ label(row.tipo) }} · {{ date(row.created_at) }}</small></div><b :class="row.importe_centavos<0?'negative':'positive'">{{ money(row.importe_centavos) }}</b></div><p v-if="!content.movimientos.length" class="muted">Sin movimientos todavía.</p></template></template>
<template v-else-if="module==='cuentas'"><div class="detail-status"><StatusBadge :value="item.estado"/><strong>{{ money(item.saldo_centavos) }}</strong></div><p class="muted">{{ label(item.tipo) }} · {{ item.numero }}</p><dl class="detail-list compact"><dt>Titular</dt><dd>{{ owner?.nombre || 'Cliente no encontrado' }}</dd><dt>DPI</dt><dd>{{ owner?.dpi_enmascarado || '—' }}</dd><dt>Correo</dt><dd>{{ owner?.email || '—' }}</dd><dt>Banca Virtual</dt><dd>{{ owner?.acceso_app ? 'Con acceso: el cliente ve esta cuenta en la app' : 'Sin acceso a la app' }}</dd></dl><div v-if="can('cuentas.manage')" class="detail-actions"><button class="secondary" @click="$emit('action','estado-cuenta',item)"><LockKeyhole :size="16"/>{{ item.estado==='activa'?'Bloquear cuenta':'Activar cuenta' }}</button></div><h3>Movimientos recientes</h3><div v-for="row in content?.data" :key="row.id" class="movement"><div><b>{{ row.concepto }}</b><small>{{ label(row.tipo) }} · {{ date(row.created_at) }}</small></div><b :class="row.importe_centavos<0?'negative':'positive'">{{ money(row.importe_centavos) }}</b></div><p v-if="!content?.data?.length" class="muted">Esta cuenta aún no tiene movimientos.</p></template>
<template v-else-if="module==='tarjetas'"><div class="detail-status"><StatusBadge :value="item.estado"/><span>•••• {{ item.ultimos_cuatro }}</span></div><div class="detail-stats"><div><small>Límite</small><b>{{ money(item.limite_centavos) }}</b></div><div><small>Capital pendiente</small><b>{{ money(item.principal_centavos) }}</b></div><div><small>Intereses</small><b>{{ money(item.interes_centavos) }}</b></div></div><p v-if="item.dia_corte" class="notice">Corte el día {{ item.dia_corte }} y pago el día {{ item.dia_pago }} de cada mes. El saldo de cada corte se debita automáticamente de la cuenta {{ accountNumber(item.cuenta_id) }}.</p><div v-if="can('tarjetas.write')" class="detail-actions"><button class="primary" @click="$emit('action','consumo',item)">Registrar consumo</button><button v-if="item.tipo==='credito'" class="secondary" @click="$emit('action','pago',item)">Registrar pago</button><button class="secondary" @click="$emit('action','estado-tarjeta',item)">{{ item.estado==='activa'?'Bloquear':'Activar' }}</button></div><h3>Estados de cuenta</h3><div v-for="row in content?.data" :key="row.id" class="statement-card"><div><b>{{ row.periodo }}</b><strong>{{ money(row.saldo_centavos) }}</strong></div><p>Pago mínimo: {{ money(row.minimo_centavos) }} · Pagado: {{ money(row.abonado_centavos ?? row.pagado_centavos) }}</p><small>Fecha de corte: {{ day(row.fecha_corte) }} · Pagar antes de: {{ day(row.fecha_pago) }}<template v-if="row.cargo_automatico"> · Cargo automático: {{ label(row.cargo_automatico.resultado) }}</template></small></div><p v-if="!content?.data?.length" class="muted">El estado de cuenta aparecerá en la próxima fecha de corte.</p></template>
<template v-else-if="module==='clientes'"><div class="detail-status"><StatusBadge :value="content?.acceso_app ? (content.activo && !content.bloqueado_hasta ? 'activa' : 'bloqueada') : 'por_configurar'"/><span class="muted">{{ content?.acceso_app ? 'Con acceso a Banca Virtual' : 'Sin perfil en la app' }}</span></div><dl class="detail-list"><dt>Nombre</dt><dd>{{ item.nombre }}</dd><dt>DPI</dt><dd>{{ item.dpi_enmascarado || '—' }}</dd><dt>Correo</dt><dd>{{ item.email || '—' }}</dd><dt>Teléfono</dt><dd>{{ item.telefono || '—' }}</dd><dt>NIT</dt><dd>{{ item.nit || '—' }}</dd><dt>Fecha de nacimiento</dt><dd>{{ item.fecha_nacimiento || '—' }}</dd><dt>Ingreso mensual</dt><dd>{{ item.ingreso_centavos == null ? '—' : money(item.ingreso_centavos) }}</dd><dt>Origen</dt><dd>{{ item.origen === 'banca_virtual' ? 'Banca Virtual' : item.origen === 'agencia' ? 'Agencia' : item.origen || '—' }}</dd><dt>Cuentas</dt><dd>{{ (lookups?.cuentas || []).filter(a=>a.cliente_id===identifier(item)).map(a=>`${a.numero} (${label(a.tipo)})`).join(', ') || 'Sin cuentas' }}</dd><dt>Registro</dt><dd>{{ date(item.created_at) }}</dd></dl><h3>Credenciales de Banca Virtual</h3><p v-if="!content?.acceso_app" class="notice">Este cliente todavía no tiene contraseña de Banca Virtual. Asígnale una para que inicie sesión con su correo.</p><template v-else><div class="detail-stats"><div><small>Acceso</small><b>{{ content.activo ? (content.bloqueado_hasta ? 'Bloqueo temporal' : 'Activo') : 'Bloqueado por el banco' }}</b></div><div><small>Intentos fallidos</small><b>{{ content.intentos_fallidos }}</b></div><div><small>Sesiones abiertas</small><b>{{ content.sesiones.length }}</b></div></div><p v-if="content.bloqueado_hasta" class="notice">Bloqueado por intentos fallidos hasta {{ date(content.bloqueado_hasta) }}. Reactivar el acceso lo desbloquea de inmediato.</p><div v-for="s in content.sesiones" :key="s.id" class="movement"><div><b>{{ s.dispositivo || 'Dispositivo no informado' }}</b><small>{{ s.ip ? `IP ${s.ip} · ` : '' }}Inició {{ date(s.inicio) }} · Vence {{ date(s.vence) }}</small></div></div><div v-if="can('clientes.manage')" class="detail-actions"><button class="secondary" @click="$emit('action','acceso-cliente',content)"><LockKeyhole :size="16"/>{{ content.activo && !content.bloqueado_hasta ? 'Bloquear acceso' : 'Reactivar acceso' }}</button><button v-if="content.sesiones.length" class="secondary" @click="$emit('action','cerrar-sesiones-cliente',content)">Cerrar sesiones</button></div></template><div v-if="can('clientes.manage')" class="detail-actions"><button class="primary" @click="$emit('action','contrasena-cliente',{...item,acceso_app:content?.acceso_app})"><LockKeyhole :size="16"/>{{ content?.acceso_app ? 'Cambiar contraseña' : 'Asignar contraseña de Banca Virtual' }}</button></div></template>
<template v-else-if="module==='planillas'"><div class="detail-status"><StatusBadge :value="item.estado"/><strong>{{ money(item.total_centavos) }}</strong></div><p class="muted">{{ item.empresa_nombre || companyName(item.empresa_id) }}<template v-if="item.pagada_el"> · pagada {{ date(item.pagada_el) }}</template></p><p v-if="item.ultimo_error" class="error-box">{{ item.ultimo_error }}</p><div v-for="(row,index) in item.pagos" :key="index" class="movement"><div><b>{{ row.nombre }}</b><small>{{ row.puesto ? `${row.puesto} · ` : '' }}Cuenta {{ row.cuenta_numero || row.cuenta_id }}</small></div><b>{{ money(row.centavos) }}</b></div><p v-if="item.estado==='pendiente_autorizacion'" class="notice">Al autorizarla se debita {{ money(item.total_centavos) }} de la cuenta de la empresa y se acredita a cada colaborador en el mismo instante: o se pagan todos o ninguno.</p><button v-if="canApprovePayroll" class="primary" @click="$emit('action','autorizar',item)">Revisar, autorizar y pagar</button></template>
<template v-else><dl class="detail-list"><template v-for="(value,key) in item" :key="key"><template v-if="!['id','_id','password','updated_at','miembros','demo'].includes(key) && value !== null && value !== ''"><dt>{{ label(key) }}</dt><dd>{{ key.endsWith('_centavos') ? money(value) : key==='empresa_id' ? (companyName(value) || value) : key==='role' ? label(value) : typeof value==='object' ? JSON.stringify(value,null,2) : value }}</dd></template></template></dl><button v-if="module==='productos' && item.type!=='prestamo' && can('productos.write')" class="primary" @click="$emit('action','editar-producto',item)">Editar política del producto</button><div v-if="module==='usuarios' && can('usuarios.write')" class="detail-actions"><button v-if="identifier(item)!==identifier(currentUser)" class="primary" @click="$emit('action','editar-usuario',item)">Actualizar rol y acceso</button><button class="secondary" @click="$emit('action','contrasena-usuario',item)"><LockKeyhole :size="16"/>Cambiar contraseña</button></div></template></div></dialog></template>
